style:
.fc{--navy:#0b2447;--navy2:#19376d;--blue:#2f6fb5;--bg:#f2f5fa;--card:#fff;--ink:#1a2536;--mut:#66758a;--line:#dfe6f0;
  --ok:#1b8a5a;--okbg:#e3f5ec;--warn:#b7791f;--warnbg:#fdf3dc;--bad:#c53030;--badbg:#fde8e8;--ret:#c05621;--retbg:#feebdc;--gray:#5b6678;--graybg:#eceff4;
  font-family:system-ui,-apple-system,"Segoe UI",Roboto,"Noto Sans Arabic","Noto Naskh Arabic",Tahoma,Arial,sans-serif;
  color:var(--ink);background:var(--bg);font-size:13px;line-height:1.45;box-sizing:border-box;padding:12px;border-radius:10px;min-height:400px}
.fc *,.fc *:before,.fc *:after{box-sizing:border-box}
.fc[dir=rtl]{text-align:right}
.fc button,.fc select,.fc input{font:inherit;color:inherit}
.fc h1,.fc h2,.fc h3{margin:0;font-weight:650}

/* header */
.fc-head{display:flex;justify-content:space-between;align-items:center;gap:12px;flex-wrap:wrap;background:linear-gradient(120deg,var(--navy),var(--navy2));color:#fff;border-radius:10px;padding:14px 18px}
.fc-title{display:flex;align-items:center;gap:12px}
.fc-title h1{font-size:19px;letter-spacing:.2px}
.fc-logo{width:40px;height:40px;border-radius:9px;background:#fff;color:var(--navy);display:grid;place-items:center;font-weight:800}
.fc-sub{opacity:.8;font-size:12px;margin-top:2px}
.fc-head-actions{display:flex;gap:8px;align-items:center}
.fc-btn{border:1px solid transparent;border-radius:7px;padding:7px 14px;cursor:pointer;font-weight:600;text-decoration:none;display:inline-flex;align-items:center;gap:6px}
.fc-btn-ghost{background:rgba(255,255,255,.14);color:#fff;border-color:rgba(255,255,255,.35)}
.fc-btn-ghost:hover{background:rgba(255,255,255,.25)}
.fc-btn-light{background:#fff;color:var(--navy);border-color:var(--line)}
.fc-btn-light:hover{background:#eef3fb}
.fc-btn.busy .fc-ic{animation:fcspin 1s linear infinite;display:inline-block}
@keyframes fcspin{to{transform:rotate(360deg)}}
.fc-seg{display:inline-flex;border:1px solid rgba(255,255,255,.4);border-radius:7px;overflow:hidden}
.fc-seg button{background:transparent;border:0;color:#fff;padding:7px 12px;cursor:pointer}
.fc-seg button.on{background:#fff;color:var(--navy);font-weight:700}
.fc-seg-inline{border-color:var(--line);margin:12px 0 8px;background:#fff}
.fc-seg-inline button{color:var(--navy)}
.fc-seg-inline button.on{background:var(--navy);color:#fff}

/* filters */
.fc-filters,.fc-toolbar{display:flex;flex-wrap:wrap;gap:10px;align-items:flex-end;background:var(--card);border:1px solid var(--line);border-radius:10px;padding:10px 12px;margin-top:10px}
.fc-toolbar{margin:0 0 10px}
.fc-f{display:flex;flex-direction:column;gap:3px;font-size:11px;color:var(--mut);font-weight:600;min-width:120px}
.fc-f select,.fc-f input{border:1px solid var(--line);border-radius:6px;padding:6px 8px;background:#fff;color:var(--ink);font-size:13px;font-weight:400;min-height:32px}
.fc-f-search{flex:1 1 200px}
.fc-hint{color:var(--mut);font-size:11px;align-self:center}
.fc-note{color:var(--mut);font-size:12px;margin:8px 2px}
.fc-check{display:flex;gap:6px;align-items:center;margin:4px 2px;font-size:12px;color:var(--mut)}
.fc-err{background:var(--badbg);color:var(--bad);border:1px solid #f4b6b6;border-radius:8px;padding:8px 12px;margin:8px 0;font-size:12px}
.fc-err[hidden]{display:none}

/* tabs */
.fc-tabs{display:flex;gap:4px;overflow-x:auto;margin-top:12px;border-bottom:2px solid var(--line);scrollbar-width:thin}
.fc-tabs button{background:transparent;border:0;border-bottom:3px solid transparent;margin-bottom:-2px;padding:10px 14px;cursor:pointer;white-space:nowrap;color:var(--mut);font-weight:600}
.fc-tabs button:hover{color:var(--navy)}
.fc-tabs button.on{color:var(--navy);border-bottom-color:var(--navy)}
.fc-main{margin-top:12px}
.fc-panel{display:none}
.fc-panel.on{display:block}

/* KPI */
.fc-kpis{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px;margin-bottom:12px}
.fc-kpi{background:var(--card);border:1px solid var(--line);border-inline-start:4px solid var(--navy2);border-radius:9px;padding:11px 13px;cursor:pointer;text-align:start;transition:box-shadow .15s,transform .15s;min-height:84px}
.fc-kpi:hover{box-shadow:0 4px 14px rgba(11,36,71,.14);transform:translateY(-1px)}
.fc-kpi .l{font-size:11.5px;color:var(--mut);font-weight:600}
.fc-kpi .v{font-size:23px;font-weight:750;color:var(--navy);margin-top:3px;font-variant-numeric:tabular-nums;direction:ltr;display:block}
.fc[dir=rtl] .fc-kpi .v{text-align:right}
.fc-kpi .s{font-size:11px;color:var(--mut);margin-top:1px}
.fc-kpi.warn{border-inline-start-color:var(--warn)}
.fc-kpi.bad{border-inline-start-color:var(--bad)}
.fc-kpi.ok{border-inline-start-color:var(--ok)}
.fc-kpi.static{cursor:default}
.fc-kpi .sk,.fc-sk{display:block;height:22px;width:60%;border-radius:5px;background:linear-gradient(90deg,#e8edf5,#f5f8fc,#e8edf5);background-size:200% 100%;animation:fcsk 1.2s infinite}
@keyframes fcsk{to{background-position:-200% 0}}
.fc-kpi .nd{font-size:15px;color:var(--mut);font-weight:600}

/* cards & charts */
.fc-card{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:12px 14px;margin-bottom:12px;min-width:0}
.fc-card h3{font-size:13.5px;color:var(--navy);margin-bottom:8px}
.fc-charts{display:grid;grid-template-columns:repeat(auto-fit,minmax(340px,1fr));gap:12px;margin-bottom:0}
.fc-charts .fc-wide{grid-column:1/-1}
.fc-chart{min-height:200px;direction:ltr}
.fc-chart .chart-legend{direction:ltr}
.fc-empty{display:grid;place-items:center;min-height:120px;color:var(--mut);text-align:center;padding:14px}
.fc-load{display:grid;place-items:center;min-height:120px;color:var(--mut)}
.fc-load:before{content:"";width:22px;height:22px;border:3px solid var(--line);border-top-color:var(--navy);border-radius:50%;animation:fcspin .8s linear infinite;margin-bottom:6px}
.fc-load{justify-items:center}

/* tables */
.fc-tablewrap{overflow-x:auto}
.fc table{width:100%;border-collapse:collapse;font-size:12.5px}
.fc th{background:#eaf0f9;color:var(--navy);font-weight:700;padding:8px 9px;text-align:start;white-space:nowrap;position:sticky;top:0}
.fc td{padding:7px 9px;border-bottom:1px solid var(--line);vertical-align:middle}
.fc tbody tr:hover{background:#f4f8fd}
.fc tr.click{cursor:pointer}
.fc td.num,.fc th.num{text-align:end;font-variant-numeric:tabular-nums;white-space:nowrap}
.fc td.num{direction:ltr}
.fc td.id{color:var(--blue);font-weight:600;white-space:nowrap;direction:ltr;text-align:start}
.fc[dir=rtl] td.id{text-align:right}
.fc tr.flag td{background:#fff6f6}
.fc .tot td{font-weight:700;background:#f4f7fc}
.fc-pager{display:flex;justify-content:space-between;align-items:center;gap:8px;margin-top:8px;flex-wrap:wrap;color:var(--mut);font-size:12px}
.fc-pager button{border:1px solid var(--line);background:#fff;border-radius:6px;padding:5px 11px;cursor:pointer}
.fc-pager button:disabled{opacity:.4;cursor:default}
.fc-badge{display:inline-block;padding:2px 8px;border-radius:20px;font-size:11px;font-weight:650;white-space:nowrap}
.b-ok{background:var(--okbg);color:var(--ok)}
.b-warn{background:var(--warnbg);color:var(--warn)}
.b-bad{background:var(--badbg);color:var(--bad)}
.b-ret{background:var(--retbg);color:var(--ret)}
.b-gray{background:var(--graybg);color:var(--gray)}
.b-blue{background:#e3eefb;color:var(--blue)}
.fc-dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-inline-end:6px}

/* attention */
.fc-attn{display:grid;grid-template-columns:repeat(auto-fit,minmax(300px,1fr));gap:12px}
.fc-attn .grp{border:1px solid var(--line);border-radius:9px;padding:9px 11px;background:#fbfcfe}
.fc-attn h4{margin:0 0 6px;font-size:12.5px;color:var(--navy);display:flex;justify-content:space-between;gap:6px}
.fc-attn .it{display:flex;justify-content:space-between;gap:8px;padding:5px 0;border-bottom:1px dashed var(--line);cursor:pointer;font-size:12px}
.fc-attn .it:last-child{border-bottom:0}
.fc-attn .it:hover{color:var(--blue)}
.fc-attn .it .a{direction:ltr;font-variant-numeric:tabular-nums;white-space:nowrap;color:var(--mut)}
.fc-link{color:var(--blue);cursor:pointer;font-weight:600;background:none;border:0;padding:0;text-decoration:underline}

/* drawer + modal */
.fc-drawer,.fc-modal{position:fixed;inset:0;background:rgba(11,36,71,.45);z-index:1050;display:flex;justify-content:flex-end}
.fc-drawer[hidden],.fc-modal[hidden]{display:none}
.fc-modal{justify-content:center;align-items:center;z-index:1060}
.fc-drawer-card{background:var(--bg);width:min(1100px,96vw);height:100%;overflow:auto;padding:14px;box-shadow:-6px 0 24px rgba(0,0,0,.25)}
.fc[dir=rtl] .fc-drawer{justify-content:flex-start}
.fc-modal-card{background:#fff;width:min(820px,96vw);max-height:92vh;overflow:auto;border-radius:12px;padding:14px 16px}
.fc-drawer-head{display:flex;justify-content:space-between;align-items:center;gap:10px;margin-bottom:10px;color:var(--navy)}
.fc-drawer-head h2{font-size:16px}
.fc-x{border:0;background:#e6ecf6;border-radius:50%;width:30px;height:30px;cursor:pointer;color:var(--navy)}
.fc-kv{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:8px 14px;margin:8px 0}
.fc-kv div{border-bottom:1px solid var(--line);padding-bottom:4px}
.fc-kv b{display:block;font-size:10.5px;color:var(--mut);font-weight:600}
.fc-kv span{word-break:break-word}
.fc-sec{margin:14px 0 6px;font-size:13px;font-weight:700;color:var(--navy)}
.fc-trail li{margin:3px 0}

/* responsive */
@media (max-width:760px){
  .fc{padding:8px}
  .fc-title h1{font-size:15px}
  .fc-filters{padding:8px}
  .fc-f{min-width:calc(50% - 6px);flex:1 1 calc(50% - 6px)}
  .fc-f-search{flex-basis:100%}
  .fc-kpis{grid-template-columns:repeat(2,1fr)}
  .fc-kpi .v{font-size:18px}
  .fc-charts{grid-template-columns:1fr}
  .fc-drawer-card{width:100vw;padding:10px}
  .fc th,.fc td{padding:6px}
}
@media print{.fc-drawer,.fc-modal{display:none}}
